import React, { useState, useEffect } from 'react';
import {
  TextField, Button, Container, Typography, Paper, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Chip, Box, Alert,
  CssBaseline, useMediaQuery, Zoom, Grid, ThemeProvider, createTheme, Fade,
} from '@mui/material';
import { teal, orange, red, grey } from '@mui/material/colors';

const theme = createTheme({
  palette: {
    primary: {
      main: teal[600],
    },
    secondary: {
      main: orange[600],
    },
    background: {
      default: '#fafafa',
      paper: '#ffffff',
    },
    error: {
      main: red[700],
    },
    text: {
      primary: '#222222',
      secondary: '#555555',
    },
  },
  typography: {
    fontFamily: "'Arial', sans-serif",
    h3: {
      fontWeight: 600,
      color: teal[700],
    },
    h6: {
      fontWeight: 500,
      color: '#444',
    },
    button: {
      textTransform: 'none',
      fontWeight: 600,
      borderRadius: 6,
      padding: '10px 20px',
    },
  },
  shape: {
    borderRadius: 6,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          transition: 'background-color 0.3s ease',
          '&:hover': {
            backgroundColor: teal[700],
          },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          padding: '24px',
          borderRadius: 6,
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
          backgroundColor: '#fff',
        },
      },
    },
    MuiTableCell: {
      styleOverrides: {
        root: {
          fontSize: 14,
          padding: '12px 16px',
        },
        head: {
          backgroundColor: teal[600],
          color: '#fff',
          fontWeight: 600,
          fontSize: 14,
          position: 'sticky',
          top: 0,
          zIndex: 2,
        },
      },
    },
  },
});

function App() {
  const [website, setWebsite] = useState('');
  const [monitoringStatus, setMonitoringStatus] = useState('Idle');
  const [threatDetected, setThreatDetected] = useState(false);
  const [message, setMessage] = useState('');
  const [threatLogs, setThreatLogs] = useState([]);
  const [lastChecked, setLastChecked] = useState(null);

  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const startMonitoring = async () => {
    if (!website) {
      setMessage('Please enter a website URL.');
      return;
    }
    setMessage('');
    try {
      const response = await fetch('http://127.0.0.1:5001/start_monitoring', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ website }),
      });
      const data = await response.json();
      if (response.ok) {
        setMessage(data.message);
        setMonitoringStatus('Monitoring');
      } else {
        setMessage(data.error || 'Failed to start monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  const stopMonitoring = async () => {
    try {
      const response = await fetch('http://127.0.0.1:5001/stop_monitoring', { method: 'POST' });
      if (response.ok) {
        setMonitoringStatus('Idle');
        setThreatDetected(false);
        setThreatLogs([]);
        setMessage('Monitoring stopped.');
        setLastChecked(null);
      } else {
        setMessage('Failed to stop monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  useEffect(() => {
    setThreatLogs([]);

    let interval = null;

    if (monitoringStatus === 'Monitoring') {
      interval = setInterval(async () => {
        try {
          const response = await fetch('http://127.0.0.1:5001/status');
          const data = await response.json();
          setMonitoringStatus(data.status);
          setThreatDetected(data.threat_detected);
          setLastChecked(new Date().toLocaleTimeString());

          const logsResponse = await fetch('http://127.0.0.1:5001/threat_logs');
          const logsData = await logsResponse.json();
          const cleanedLogs = logsData.map(log => {
            let cleanedWebsite = log.website;
            if (cleanedWebsite.startsWith('http://')) {
              cleanedWebsite = cleanedWebsite.slice(7);
            } else if (cleanedWebsite.startsWith('https://')) {
              cleanedWebsite = cleanedWebsite.slice(8);
            }
            return { ...log, website: cleanedWebsite };
          });
          setThreatLogs(cleanedLogs);
        } catch (error) {
          setMonitoringStatus('Error');
          setThreatDetected(false);
          setThreatLogs([]);
          setLastChecked(null);
        }
      }, 5000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [monitoringStatus]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'Monitoring':
        return 'primary';
      case 'Idle':
        return 'default';
      case 'Starting':
        return 'secondary';
      default:
        return 'default';
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Container maxWidth="md" sx={{ mt: 4, mb: 4, pl: '1.5cm', pr: '1.5cm' }}>
        <Typography variant={isMobile ? 'h5' : 'h4'} align="center" sx={{ fontWeight: 'bold', mb: 3 }}>
          Cyber Threat Detection System
        </Typography>
        <Typography variant="subtitle1" align="center" sx={{ mb: 3, color: grey[600] }}>
          Real-time Website Cyber Threat Monitoring and Detection
        </Typography>
        <Box sx={{ textAlign: 'center', mb: 2 }}>
          <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
            {lastChecked ? `Last checked at: ${lastChecked}` : 'Monitoring not started'}
          </Typography>
        </Box>
        <Grid container spacing={3}>
          <Grid item xs={12} md={5}>
            <Paper elevation={3} sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
              <TextField
                label="Website URL"
                variant="outlined"
                fullWidth
                value={website}
                onChange={(e) => setWebsite(e.target.value)}
                required
              />
              <Button variant="contained" color="primary" onClick={startMonitoring} fullWidth>
                Start Monitoring
              </Button>
              <Button variant="outlined" color="error" onClick={stopMonitoring} fullWidth>
                Stop Monitoring
              </Button>
              {message && (
                <Zoom in={Boolean(message)}>
                  <Alert severity="info" sx={{ mt: 2 }}>
                    {message}
                  </Alert>
                </Zoom>
              )}
              <Box sx={{ mt: 3, textAlign: 'center' }}>
                <Typography variant="subtitle1" component="span" sx={{ fontWeight: 'medium' }}>
                  Status:
                </Typography>
                <Chip
                  label={monitoringStatus}
                  color={threatDetected ? 'error' : getStatusColor(monitoringStatus)}
                  sx={{ ml: 1, fontWeight: 'bold', fontSize: 14, px: 2, py: 0.5 }}
                />
                {threatDetected && (
                  <Fade in={threatDetected} timeout={700}>
                    <Alert severity="error" sx={{ mt: 2 }}>
                      Threat Detected on the website!
                    </Alert>
                  </Fade>
                )}
              </Box>
            </Paper>
          </Grid>
          <Grid item xs={12} md={7}>
            <Paper elevation={3} sx={{ p: 3, maxHeight: 400, overflowY: 'auto', width: '130%' }}>
              <Typography variant="h6" gutterBottom sx={{ mb: 2 }}>
                Threat Detection Log
              </Typography>
              <TableContainer sx={{ maxHeight: 420 }}>
                <Table stickyHeader aria-label="threat detection log table" sx={{ minWidth: 900 }}>
                  <TableHead>
                    <TableRow>
                      <TableCell>Timestamp</TableCell>
                      <TableCell>Website</TableCell>
                      <TableCell>Threat Name</TableCell>
                      <TableCell>Message</TableCell>
                      <TableCell>Solution</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {threatLogs.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={5} align="center" sx={{ fontStyle: 'italic' }}>
                          No threats detected yet.
                        </TableCell>
                      </TableRow>
                    ) : (
                      threatLogs.map((log) => (
                        <TableRow key={log.id} hover>
                          <TableCell>{log.timestamp}</TableCell>
                          <TableCell>{log.website}</TableCell>
                          <TableCell>{log.threat_name}</TableCell>
                          <TableCell>{log.message}</TableCell>
                          <TableCell>{log.solution}</TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </Grid>
        </Grid>
      </Container>
    </ThemeProvider>
  );
}

export default App;
